package io.knowledgebrain.collaboration;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class ReviewEventTargetApiTest {
 SubmissionApiTest f;ReviewEventTargetStore store;ReviewEventTargetController api;UUID event;
 @BeforeEach void setup(){f=new SubmissionApiTest();f.setup();store=mock(ReviewEventTargetStore.class);api=new ReviewEventTargetController(store,f.f.api,new SimpleMeterRegistry());event=new UuidV7(java.time.Clock.systemUTC()).next();}
 @Test void freshAuthorViewerAndOwnerAuthorityAndNoStore()throws Exception{for(String role:List.of("OWNER","MEMBER","VIEWER")){f.f.role(role);var result=api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),event.toString(),f.req("GET",null));assertEquals("no-store",result.getHeaders().getCacheControl());verify(store).get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,role.equals("OWNER"),event);clearInvocations(store);}verify(f.f.auth,times(3)).participation(anyString(),anyList(),anyString());}
 @Test void malformedQueriesReadBodiesAndCredentialsDenyBeforeStore(){var query=f.req("GET",null);query.addParameter("authorId",f.f.actor.toString());assertThrows(ResponseStatusException.class,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),event.toString(),query));assertThrows(ResponseStatusException.class,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),event.toString(),f.req("GET","{}")));var bad=f.req("GET",null);bad.setSecure(false);assertThrows(ResponseStatusException.class,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),event.toString(),bad));verifyNoInteractions(store);}
}
